css:
.ot { width: 320px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.ot-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.ot-area { display: block; width: 100%; padding: 12px 14px; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 8px; background: #fff; font: inherit; font-size: 14px; line-height: 1.6; color: #111827; resize: vertical; }
.ot-area::placeholder { color: #9ca3af; }
.ot-area:focus { outline: none; border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }

.ft { width: 320px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.ft-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.ft-area { display: block; width: 100%; padding: 12px 14px; box-sizing: border-box; border: 2px solid transparent; border-radius: 10px; background: #f3f4f6; font: inherit; font-size: 14px; line-height: 1.6; color: #111827; resize: none; transition: background 0.15s, border-color 0.15s; }
.ft-area:hover { background: #e5e7eb; }
.ft-area:focus { outline: none; background: #fff; border-color: #6366f1; }

.ct { width: 320px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.ct-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.ct-wrap { position: relative; }
.ct-area { display: block; width: 100%; padding: 12px 14px 30px; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 8px; background: #fff; font: inherit; font-size: 14px; line-height: 1.6; color: #111827; resize: none; }
.ct-area:focus { outline: none; border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }
.ct-count { position: absolute; right: 12px; bottom: 8px; font-size: 12px; color: #6b7280; }

.et { width: 320px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.et-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.et-area { display: block; width: 100%; padding: 12px 14px; box-sizing: border-box; border: 1px solid #ef4444; border-radius: 8px; background: #fef2f2; font: inherit; font-size: 14px; line-height: 1.6; resize: none; }
.et-area:focus { outline: none; box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.2); }
.et-error { margin: 6px 0 0; font-size: 12px; color: #b91c1c; }

.dt { width: 320px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.dt-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #9ca3af; }
.dt-area { display: block; width: 100%; padding: 12px 14px; box-sizing: border-box; border: 1px solid #e5e7eb; border-radius: 8px; background: #f3f4f6; font: inherit; font-size: 14px; line-height: 1.6; color: #9ca3af; resize: none; cursor: not-allowed; }

.rt { width: 320px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.rt-label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #374151; }
.rt-area { display: block; width: 100%; min-height: 72px; max-height: 240px; padding: 12px 14px; box-sizing: border-box; border: 1px solid #d1d5db; border-radius: 8px; background: #fff; font: inherit; font-size: 14px; line-height: 1.6; resize: vertical; }
.rt-area:focus { outline: none; border-color: #10b981; box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.2); }
.rt-hint { margin: 6px 0 0; font-size: 12px; color: #9ca3af; }
